// Episode 4 (the machine), diagrams for chapters 5 to 8 (ep4_explain.js holds chapters 1 to 4). Load after ep3_explain.js (reuses XP, xpBoard, xpFrame,
// xpOp, xpIn, xpWin, xpMono, xpAbril, xpPerson, xpArrow, xpPartial, xpCurve) and ep4.js (E4 colours).
//
//   ep4_pyramid     ch5  The machine as a pyramid: a captain for every few hundred voters (Mr. Duffy ringed), the families on his
//                        blocks, the ward bosses, the boss; favors flow down as gold glints, votes up as teal pulses.
//   ep4_citizen     ch5  Yankel's papers: arrived 1882, five years, a citizen and a voter in 1887. Mr. Duffy could count, too.
//   ep4_ledger      ch6  The courthouse ledger: the 1858 limit stamped ($250,000), the cost meter climbing to $11 to 13 million,
//                        then the bills: thermometers $7,500, carpets, shades and curtains $675,534.44, a plasterer $138,187.
//   ep4_escape      ch6  Tweed's escape: New York (December 1875) to Cuba to Vigo, Spain (1876).
//   ep4_jobs        ch7  Plunkitt in 1870: four offices at once, three paychecks.
//   ep4_graft       ch7  Honest graft: the swamp, he buys it cheap, the park plan lands on it, the city pays him.
//   ep4_tombstone   ch7  The epitaph he wanted.
//   ep4_scorecard   ch8  HELPER and THIEF, two columns filling with icons as they are read (no verdict line).
//   ep4_civil       ch8  The Pendleton Act, 1883: a civil service exam (passed a test, not voted the right way).
//
// Each renderer takes the chapter's narration time n and a cue table (word start times, from the chapter's words.json); the
// defaults below are the voiced words (Nov 15), so the CLIPS entries play as the chapter does.
// Colour rules: the Kellys coral only; the Rabinowitzes wheat gold; everyone else ink or muted grey-green; teal draws and
// explains; orange is the torn strip and the handwriting; money only as a small warm-gold glint. No em dashes in any text.

/* ---------- shared bits ---------- */
const X4 = {...XP, glint: '#FFD36B', paperLine: '#B9AE94', stamp: '#2B2418'};
// a small four-point gold glint (money): never a fill for anything else
function x4Glint(x, y, r = 10, k = 1, t = 0) {
  if (k <= 0.01) return '';
  const s = r * (0.75 + 0.25 * Math.sin(t * 9 + x * 0.05)) * k;
  return `<g opacity="${f1(Math.min(1, k) * 100) / 100}"><circle cx="${f1(x)}" cy="${f1(y)}" r="${f1(s * 0.9)}" fill="${X4.glint}" opacity="0.25"/>` +
    `<path d="M${f1(x)},${f1(y - s)} L${f1(x + s * 0.22)},${f1(y - s * 0.22)} L${f1(x + s)},${f1(y)} L${f1(x + s * 0.22)},${f1(y + s * 0.22)} L${f1(x)},${f1(y + s)} L${f1(x - s * 0.22)},${f1(y + s * 0.22)} L${f1(x - s)},${f1(y)} L${f1(x - s * 0.22)},${f1(y - s * 0.22)} Z" fill="${X4.glint}" stroke="#111" stroke-width="1.5"/></g>`;
}
// a teal pulse (a vote)
const x4Pulse = (x, y, r = 9, k = 1) => (k <= 0.01 ? '' : `<circle cx="${f1(x)}" cy="${f1(y)}" r="${f1(r * 1.9)}" fill="${X4.teal}" opacity="${f1(0.18 * k * 100) / 100}"/><circle cx="${f1(x)}" cy="${f1(y)}" r="${f1(r)}" fill="${X4.teal}" stroke="#111" stroke-width="2.5" opacity="${f1(k * 100) / 100}"/>`);
// a pop-in scale (0 -> 1 with a small overshoot)
const x4Pop = (u) => (u <= 0 ? 0 : u >= 1 ? 1 : 1 + 0.18 * Math.sin(u * Math.PI) - (1 - u) ** 3);
const x4At = (x, y, k, body) => (k <= 0.01 ? '' : `<g transform="translate(${f1(x)},${f1(y)}) scale(${f1(k * 1000) / 1000})">${body}</g>`);
// a picture-graph man with a hat: bowler (captains, bosses), top (Plunkitt), cap
function x4Man(x, y, h, col, hat = 'bowler', {stroke = '', op = 1} = {}) {
  const r = h * 0.12, hy = y - h + r, st = stroke ? ` stroke="${stroke}" stroke-width="3"` : '';
  const hatSvg = hat === 'bowler' ? `<path d="M${f1(x - r * 1.45)},${f1(hy - r * 0.55)} L${f1(x + r * 1.45)},${f1(hy - r * 0.55)} L${f1(x + r * 1.1)},${f1(hy - r * 0.75)} Q${f1(x + r)},${f1(hy - r * 1.9)} ${f1(x)},${f1(hy - r * 1.9)} Q${f1(x - r)},${f1(hy - r * 1.9)} ${f1(x - r * 1.1)},${f1(hy - r * 0.75)} Z" fill="${col}"${st}/>`
    : hat === 'top' ? `<path d="M${f1(x - r * 1.5)},${f1(hy - r * 0.55)} L${f1(x + r * 1.5)},${f1(hy - r * 0.55)} L${f1(x + r * 0.95)},${f1(hy - r * 0.8)} L${f1(x + r * 1.05)},${f1(hy - r * 2.6)} L${f1(x - r * 1.05)},${f1(hy - r * 2.6)} L${f1(x - r * 0.95)},${f1(hy - r * 0.8)} Z" fill="${col}"${st}/>`
    : hat === 'cap' ? `<path d="M${f1(x - r * 1.05)},${f1(hy - r * 0.35)} Q${f1(x)},${f1(hy - r * 1.6)} ${f1(x + r * 1.05)},${f1(hy - r * 0.35)} L${f1(x + r * 1.8)},${f1(hy - r * 0.25)} Z" fill="${col}"${st}/>` : '';
  return `<g opacity="${f1(op * 100) / 100}">` + xpPerson(x, y, h, col, {stroke}) + `<g fill="${col}">${hatSvg}</g></g>`;
}

// the desk (as the edit's desk(): near-black wood, a pool of lamp light), in SVG
const x4Desk = () => `<rect width="1920" height="1080" fill="#0B0A07"/><rect width="1920" height="1080" fill="url(#x4desk)"/>`;
const X4_DEFS = `<radialGradient id="x4desk" cx="0.5" cy="0.45" r="0.62"><stop offset="0" stop-color="#2a2620"/><stop offset="0.55" stop-color="#16140f"/><stop offset="1" stop-color="#0b0a07"/></radialGradient>`;

/* ---------- favor and scorecard icons (about 100 px; drawn centred on 0,0) ---------- */
const X4ICON = {
  job: () => `<path d="M-34,40 L18,-28" stroke="#111" stroke-width="13" stroke-linecap="round"/><path d="M-34,40 L18,-28" stroke="#8A6A44" stroke-width="7" stroke-linecap="round"/>` +
    `<path d="M10,-20 L40,-46 Q52,-40 46,-26 L22,-4 Z" fill="#5F857F" stroke="#111" stroke-width="3"/>` +
    `<path d="M-40,-30 L36,40" stroke="#111" stroke-width="13" stroke-linecap="round"/><path d="M-40,-30 L36,40" stroke="#8A6A44" stroke-width="7" stroke-linecap="round"/>` +
    `<path d="M-52,-46 Q-36,-58 -18,-44 L-30,-30 Q-40,-40 -52,-34 Z" fill="#A3BAB2" stroke="#111" stroke-width="3"/>`,
  coal: () => `<path d="M-44,-6 L44,-6 L34,46 L-34,46 Z" fill="#2B3B39" stroke="#111" stroke-width="3"/><path d="M-50,-10 L50,-10 L46,-2 L-46,-2 Z" fill="#3E5F5A" stroke="#111" stroke-width="3"/>` +
    [[-30, -16, 14], [-10, -24, 16], [12, -20, 15], [30, -14, 12], [0, -36, 13], [-20, -32, 10], [20, -32, 10]].map(([x, y, r]) => `<path d="M${x - r},${y} L${x - r * 0.3},${y - r} L${x + r * 0.8},${y - r * 0.6} L${x + r},${y + r * 0.4} L${x},${y + r * 0.8} Z" fill="#111" stroke="#5F857F" stroke-width="1.5"/>`).join('') +
    `<path d="M-34,6 q-26,0 -26,20" fill="none" stroke="#111" stroke-width="6"/>`,
  judge: () => `<rect x="-46" y="26" width="92" height="20" rx="4" fill="#5A4430" stroke="#111" stroke-width="3"/>` +
    `<g transform="rotate(-30)"><rect x="-6" y="-14" width="12" height="74" rx="4" fill="#8A6A44" stroke="#111" stroke-width="3"/><rect x="-34" y="-40" width="68" height="34" rx="8" fill="#6B4E34" stroke="#111" stroke-width="3"/><rect x="-36" y="-34" width="6" height="22" fill="#111"/><rect x="30" y="-34" width="6" height="22" fill="#111"/></g>`,
  papers: () => `<rect x="-30" y="-46" width="64" height="86" fill="#DCCFB0" stroke="#111" stroke-width="3" transform="rotate(6)"/><rect x="-36" y="-44" width="64" height="86" fill="${XP.paper}" stroke="#111" stroke-width="3"/>` +
    [0, 1, 2, 3, 4].map((k) => `<rect x="-26" y="${-30 + k * 12}" width="${k === 4 ? 24 : 44}" height="3" fill="#7A6F58"/>`).join('') + `<circle cx="14" cy="28" r="12" fill="#8A3A2A" stroke="#111" stroke-width="2.5"/><path d="M8,38 l-6,16 l8,-4 l4,8 l2,-16" fill="#8A3A2A" stroke="#111" stroke-width="2"/>`,
  fire: () => `<path d="M-44,46 L-44,-14 L0,-50 L44,-14 L44,46 Z" fill="#2B4744" stroke="#111" stroke-width="3"/><rect x="-28" y="-4" width="20" height="24" fill="#FFB15C" stroke="#111" stroke-width="2.5"/><rect x="8" y="-4" width="20" height="24" fill="#FFB15C" stroke="#111" stroke-width="2.5"/>` +
    `<path d="M-20,-6 q-8,-14 2,-24 q2,12 8,10 q2,-10 10,-14 q-2,16 2,28 Z" fill="#FF9F1C" opacity="0.8"/><rect x="-8" y="26" width="16" height="20" fill="#111"/>`,
  build: () => `<path d="M-50,-14 L0,-46 L50,-14 Z" fill="#A3BAB2" stroke="#111" stroke-width="3"/><rect x="-50" y="-14" width="100" height="8" fill="#5F857F" stroke="#111" stroke-width="3"/>` +
    [-38, -16, 6, 28].map((x) => `<rect x="${x}" y="-6" width="10" height="42" fill="#A3BAB2" stroke="#111" stroke-width="2.5"/>`).join('') + `<rect x="-56" y="36" width="112" height="10" fill="#5F857F" stroke="#111" stroke-width="3"/>`,
  bag: () => `<path d="M-14,-34 L14,-34 L8,-24 Q44,-4 38,28 Q32,46 0,46 Q-32,46 -38,28 Q-44,-4 -8,-24 Z" fill="#3E5F5A" stroke="#111" stroke-width="3"/><path d="M-16,-30 L16,-30" stroke="#111" stroke-width="5"/>`,
  people: () => [[-30, 46, 64, false], [0, 46, 76, true], [30, 46, 60, false]].map(([x, y, h, s]) => xpPerson(x, y, h, '#5F857F', {skirt: s, stroke: '#111'})).join(''),
  ballot: () => `<rect x="-42" y="-8" width="84" height="54" fill="#5A4430" stroke="#111" stroke-width="3"/><rect x="-14" y="-10" width="28" height="6" fill="#111"/>` +
    `<rect x="-14" y="-52" width="28" height="44" fill="${XP.paper}" stroke="#111" stroke-width="2.5" transform="rotate(-8)"/><rect x="-8" y="-58" width="28" height="44" fill="${XP.paper}" stroke="#111" stroke-width="2.5" transform="rotate(10)"/>`,
  tag: () => `<path d="M-40,-24 L24,-24 L48,0 L24,24 L-40,24 Z" fill="${XP.paper}" stroke="#111" stroke-width="3"/><circle cx="26" cy="0" r="6" fill="${XP.bg}" stroke="#111" stroke-width="2"/><path d="M26,-6 Q40,-40 10,-46" fill="none" stroke="#111" stroke-width="3"/>` +
    `<rect x="-30" y="-8" width="40" height="5" fill="#7A6F58"/><rect x="-30" y="4" width="28" height="5" fill="#7A6F58"/>`,
  boss: () => x4Man(0, 48, 96, '#1A2422', 'bowler', {stroke: '#5F857F'}),
  exam: () => `<rect x="-36" y="-46" width="72" height="92" fill="${XP.paper}" stroke="#111" stroke-width="3"/>` + [0, 1, 2].map((k) => `<rect x="-26" y="${-30 + k * 24}" width="12" height="12" fill="none" stroke="#111" stroke-width="2"/><rect x="-8" y="${-26 + k * 24}" width="34" height="4" fill="#7A6F58"/>`).join('') +
    `<path d="M-26,-26 l5,6 l10,-12" fill="none" stroke="${XP.teal}" stroke-width="4"/>`,
};
const x4Icon = (name, x, y, k = 1, extra = '') => x4At(x, y, k, X4ICON[name]() + extra);

/* ================= ep4_pyramid (ch5): captain, ward boss, boss ================= */
const PY_CUE = {pyr: 11.36, bottom: 13.02, captain: 14.04, duffy: 16.48, knew: 17.6, sick: 20.32, work: 21.2, baby: 22.6, above: 23.76, ward: 24.7, top: 25.78, boss: 26.86, picked: 28.08, jobs: 29.94};
const PY = {cx: 600, base: 800, wy: 560, by: 330, n: 9, x0: 150, x1: 970};
function renderPyramid(n, C = PY_CUE) {
  const s = [xpBoard(4)], scr = [];
  const z = 1 + 0.04 * smooth(C.pyr, C.jobs + 1.5, n), zx = 560, zy = 560;
  // the pyramid's outline draws on first (dashed teal)
  const tri = [[PY.x0 - 40, PY.base + 170], [PY.cx, PY.by - 120], [PY.x1 + 40, PY.base + 170], [PY.x0 - 40, PY.base + 170]];
  s.push(xpOp(0.55, xpArrow(tri, xpIn(C.pyr, n, 1.2), {w: 4, dash: '3 12', head: false})));
  const capX = (i) => PY.x0 + (PY.x1 - PY.x0) * i / (PY.n - 1), wardOf = (i) => Math.floor(i / 3), wardX = (w) => PY.cx + (w - 1) * 330, duffy = 4;
  // lines: captains up to their ward boss, ward bosses up to the boss
  const upK = xpIn(C.above, n, 0.9), topK = xpIn(C.top, n, 0.9);
  for (let i = 0; i < PY.n; i++) { const a = [capX(i), PY.base - 122], b = [wardX(wardOf(i)), PY.wy + 6]; s.push(xpOp(0.8, xpArrow([a, b], upK, {w: 3, head: false}))); }
  for (let w = 0; w < 3; w++) s.push(xpOp(0.9, xpArrow([[wardX(w), PY.wy - 120], [PY.cx, PY.by + 10]], topK, {w: 4, head: false})));
  // the blocks under each captain: three little houses; Mr. Duffy's light up as the narration names who he knew
  for (let i = 0; i < PY.n; i++) {
    const k = x4Pop(xpIn(C.bottom + 0.15 * i, n, 0.4)), lit = i === duffy ? smooth(C.knew, C.knew + 0.5, n) : 0;
    for (let h = 0; h < 3; h++) { const hx = capX(i) - 32 + h * 32; s.push(xpOp(k, `<path d="M${hx - 12},${PY.base + 120} l0,-26 l12,-12 l12,12 l0,26 Z" fill="${lit > 0.5 ? '#3E5F5A' : XP.mute2}" stroke="#111" stroke-width="2"/>` +
      (lit > 0 ? `<rect x="${hx - 5}" y="${PY.base + 98}" width="10" height="10" fill="#FFF3D6" opacity="${f1(lit * 0.9)}"/>` : ''))); }
  }
  // the captains: ink men in bowlers; Mr. Duffy ringed
  for (let i = 0; i < PY.n; i++) { const k = x4Pop(xpIn(C.captain + 0.08 * i, n, 0.35)); s.push(x4At(capX(i), PY.base, k, x4Man(0, 0, 112, '#1A2422', 'bowler', {stroke: '#A3BAB2'}))); }
  const dk = xpIn(C.duffy, n, 0.4);
  if (dk > 0) s.push(`<ellipse cx="${capX(duffy)}" cy="${PY.base - 54}" rx="${f1(56 * dk)}" ry="${f1(84 * dk)}" fill="none" stroke="${XP.teal}" stroke-width="5"/>` + x4Glint(capX(duffy) + 10, PY.base - 36, 6, dk, n));
  // ward bosses and the boss
  for (let w = 0; w < 3; w++) s.push(x4At(wardX(w), PY.wy, x4Pop(xpIn(C.ward + 0.12 * w, n, 0.4)), x4Man(0, 0, 130, '#1A2422', 'bowler', {stroke: '#A3BAB2'})));
  s.push(x4At(PY.cx, PY.by, x4Pop(xpIn(C.boss, n, 0.45)), x4Man(0, 0, 160, '#1A2422', 'bowler', {stroke: XP.cream})));
  // favors down (gold glints) and votes up (teal pulses) once the whole chain is there
  const flow = xpIn(C.picked, n, 0.8);
  if (flow > 0) for (let i = 0; i < PY.n; i++) {
    const c = [capX(i), PY.base - 122], wv = [wardX(wardOf(i)), PY.wy + 6], b = [PY.cx, PY.by + 10];
    const u = ((n * 0.55 + i * 0.37) % 1), v = ((n * 0.55 + i * 0.37 + 0.5) % 1);
    const down = u < 0.5 ? [lerp(b[0], wv[0], u * 2), lerp(b[1], wv[1] - 120, u * 2)] : [lerp(wv[0], c[0], u * 2 - 1), lerp(wv[1], c[1], u * 2 - 1)];
    const up = v < 0.5 ? [lerp(c[0], wv[0], v * 2), lerp(c[1], wv[1], v * 2)] : [lerp(wv[0], b[0], v * 2 - 1), lerp(wv[1] - 120, b[1], v * 2 - 1)];
    if (i % 2 === 0) s.push(x4Glint(down[0], down[1], 9, flow, n)); else s.push(x4Pulse(up[0], up[1], 7, flow));
  }
  // labels
  scr.push(xpOp(xpIn(C.pyr + 0.2, n), tapeS(110, 92, 'THE MACHINE', 54, -2, 1, 61)));
  scr.push(tag(130, 1000, 'CAPTAIN · ONE FOR EVERY FEW HUNDRED VOTERS', xpIn(C.captain, n)));
  scr.push(tag(capX(duffy) - 120, PY.base - 150, 'MR. DUFFY', xpIn(C.duffy + 0.2, n) * (1 - xpIn(C.above, n))));
  scr.push(tag(wardX(0) - 330, PY.wy - 40, 'WARD BOSS', xpIn(C.ward + 0.2, n)));
  scr.push(tag(PY.cx + 110, PY.by - 60, 'THE BOSS', xpIn(C.boss + 0.2, n)));
  // who he knew (before the card arrives on the right)
  const kn = xpWin(C.knew, C.ward + 0.5, n);
  if (kn > 0.01) {
    scr.push(xpOp(kn * xpIn(C.knew, n), penS(1120, 330, 'every family on his blocks:', 30, -3)));
    scr.push(xpOp(kn * xpIn(C.sick, n), penS(1180, 470, 'who was sick', 30, -3)));
    scr.push(xpOp(kn * xpIn(C.work, n), penS(1180, 590, 'who was out of work', 30, -3)));
    scr.push(xpOp(kn * xpIn(C.baby, n), penS(1180, 710, "who'd just had a baby", 30, -3)));
    s.push(xpOp(kn * xpIn(C.sick, n), xpArrow(xpCurve([1160, 650], [capX(duffy) + 60, PY.base + 80], 80), xpIn(C.sick, n, 0.7), {w: 4})));
  }
  scr.push(card(1010, 160 + 0 * C.ward, 'Ward boss', 'The party leader for one ward,|a district of the city, over|its captains. At the top, the|boss runs the whole machine.', null, xpIn(C.ward + 0.9, n, 0.4)));
  const bj = xpIn(C.picked - 0.3, n, 0.4);
  if (bj > 0) { scr.push(xpOp(xpIn(C.picked - 0.3, n, 0.4), penS(1040, 680, 'picks the candidates', 32, -3))); scr.push(xpOp(xpIn(C.picked - 0.1, n, 0.4), penS(1060, 800, 'hands out the city jobs', 32, -3)));
    s.push(x4Icon('ballot', PY.cx - 190, PY.by - 30, 0.75 * x4Pop(xpIn(C.picked, n, 0.4))) + x4Icon('job', PY.cx + 220, PY.by + 10, 0.7 * x4Pop(xpIn(C.jobs, n, 0.4)))); }
  return xpFrame(n, `<g transform="translate(${zx},${zy}) scale(${f1(z * 1000) / 1000}) translate(${-zx},${-zy})">${s.join('')}</g>`, scr.join(''));
}

/* ================= ep4_citizen (ch5): five years, then a vote ================= */
const CZ_CUE = {last: 47.38, rab: 48.94, empire: 51.3, father: 52.72, y1882: 53.82, after: 55.32, citizen: 57.16, vote: 58.18, meant: 58.98, y1887: 59.54, duffy: 61.2, count: 61.98};
function renderCitizen(n, C = CZ_CUE) {
  const s = [xpBoard(6)], scr = [], X = (yr) => 240 + (yr - 1882) * 250, Y = 640;
  const z = 1 + 0.035 * smooth(C.last, C.count + 1, n);
  scr.push(xpOp(xpIn(C.last, n), tapeS(110, 92, 'HELP WITH CITIZENSHIP PAPERS', 50, -2, 1, 62)));
  // the timeline
  s.push(xpOp(xpIn(C.father, n), `<rect x="${X(1882) - 40}" y="${Y}" width="${X(1887) - X(1882) + 80}" height="5" fill="${XP.pale}"/>`));
  for (let yr = 1882; yr <= 1887; yr++) {
    const k = yr === 1882 ? xpIn(C.y1882, n) : xpIn(C.after + 0.35 * (yr - 1882), n, 0.3);
    s.push(xpOp(k, `<rect x="${X(yr) - 3}" y="${Y - 18}" width="6" height="41" fill="${yr === 1887 ? XP.teal : XP.pale}"/>`));
    scr.push(xpOp(k, xpMono(X(yr), Y + 66, String(yr), 32, yr === 1887 ? XP.teal : XP.cream, 'middle')));
  }
  // Yankel, gold, walks the five years
  const wk = smooth(C.after, C.citizen, n), yx = lerp(X(1882), X(1887), wk), ya = xpIn(C.rab, n);
  s.push(xpOp(ya, xpPerson(yx, Y - 30, 200, XP.gold, {stroke: '#111'})));
  scr.push(tag(130, 230, 'THE RABINOWITZES, UPSTAIRS · FROM THE RUSSIAN EMPIRE', xpIn(C.rab, n) * (1 - xpIn(C.vote + 0.6, n))));
  scr.push(tag(X(1882) - 150, Y - 230, 'YANKEL ARRIVES · 1882', xpIn(C.y1882, n) * (1 - xpIn(C.citizen + 0.6, n))));
  // the brace: five years
  const bk = xpIn(C.after, n, 0.6);
  if (bk > 0) { const bx0 = X(1882), bx1 = lerp(X(1882), X(1887), bk), by = Y + 110;
    s.push(`<path d="M${bx0},${by} q0,22 30,22 L${f1(bx1 - 30)},${by + 22} q30,0 30,-22" fill="none" stroke="${XP.teal}" stroke-width="5"/>`);
    scr.push(xpOp(xpIn(C.after + 0.4, n), xpAbril((X(1882) + X(1887)) / 2, by + 110, '5 years', 64, XP.cream, 'middle'))); }
  // a citizen, and a voter
  const ck = x4Pop(xpIn(C.citizen, n, 0.45)), vk = x4Pop(xpIn(C.vote, n, 0.45));
  s.push(x4Icon('papers', X(1887) + 190, Y - 130, 1.5 * ck) + x4Icon('ballot', X(1887) + 190, Y - 340, 1.5 * vk));
  scr.push(tag(X(1887) - 520, Y - 300, 'A CITIZEN · AND A VOTER', xpIn(C.vote, n)));
  // 1887, ringed
  const rk = xpIn(C.meant, n, 0.5);
  if (rk > 0) s.push(`<ellipse cx="${X(1887)}" cy="${Y + 56}" rx="${f1(84 * rk)}" ry="${f1(44 * rk)}" fill="none" stroke="${XP.teal}" stroke-width="5"/>`);
  scr.push(xpOp(xpIn(C.y1887, n), penS(X(1887) - 320, Y + 300, 'an election year', 32, -3)));
  // Mr. Duffy could count, too: his little notebook, a tally
  const dk = xpIn(C.duffy, n, 0.4);
  if (dk > 0) { s.push(x4At(300, 440, 1.4 * x4Pop(dk), x4Man(0, 0, 130, '#1A2422', 'bowler', {stroke: '#A3BAB2'})) + x4Glint(316, 366, 8, dk, n));
    s.push(xpOp(dk, `<rect x="360" y="290" width="150" height="110" fill="${XP.paper}" stroke="#111" stroke-width="3" transform="rotate(-6, 435, 345)"/>` +
      [0, 1, 2, 3].map((k) => `<rect x="${384 + k * 22}" y="${316 + k * -2}" width="5" height="${f1(54 * xpIn(C.duffy + 0.25 + 0.15 * k, n, 0.2))}" fill="#111" transform="rotate(-6, 435, 345)"/>`).join('') +
      `<path d="M378,346 L476,322" stroke="#111" stroke-width="4" opacity="${f1(xpIn(C.count, n, 0.2))}"/>`)); }
  return xpFrame(n, `<g transform="translate(960,600) scale(${f1(z * 1000) / 1000}) translate(-960,-600)">${s.join('')}</g>`, scr.join(''));
}

/* ================= ep4_ledger (ch6): the courthouse accounts ================= */
const LG_CUE = {in1858: 12.04, cost: 14.34, k250: 15.5, by: 17.88, y1871: 18.06, between: 20.36, million: 22.58, still: 24.3, fin: 24.92, where: 25.92, look: 27.42, thermo: 28.8, t7500: 30.0, forT: 32.42,
  carpets: 34.12, c675: 36.74, plast: 39.52, p138: 41.02, two: 44.56, dec: 46.04, prince: 47.26, end: 50.9};
function renderLedger(n, C = LG_CUE) {
  const s = [], scr = [];
  // the camera: the whole page and the meter, then closer on the lines as the bills are read
  const zk = smooth(C.look - 0.6, C.thermo + 0.4, n), z = lerp(1.0, 1.12, zk) + 0.02 * smooth(C.thermo, C.end, n), fx = lerp(960, 760, zk), fy = lerp(540, 600, zk);
  s.push(x4Desk());
  // the ledger page
  const P = {x: 150, y: 120, w: 1060, h: 860};
  s.push(`<rect x="${P.x + 14}" y="${P.y + 22}" width="${P.w}" height="${P.h}" fill="#000" opacity="0.5" filter="url(#soft)"/><rect x="${P.x}" y="${P.y}" width="${P.w}" height="${P.h}" fill="#EDE4D0"/>` +
    `<rect x="${P.x}" y="${P.y}" width="${P.w}" height="${P.h}" fill="url(#lgpaper)" opacity="0.5"/>`);
  for (let k = 0; k < 15; k++) s.push(`<rect x="${P.x + 30}" y="${P.y + 200 + k * 46}" width="${P.w - 60}" height="1.5" fill="${X4.paperLine}"/>`);
  s.push(`<rect x="${P.x + 790}" y="${P.y + 170}" width="2" height="${P.h - 200}" fill="#B5463D" opacity="0.6"/><rect x="${P.x + 80}" y="${P.y + 170}" width="2" height="${P.h - 200}" fill="#B5463D" opacity="0.6"/>`);
  scr.push(`<g>${xpAbril(P.x + 60, P.y + 92, 'New County Court House', 56, X4.ink)}${xpMono(P.x + 62, P.y + 140, 'ACCOUNTS OF THE COUNTY · NEW YORK', 22, '#5A5040')}</g>`);
  // the stamp: the 1858 limit
  const st = xpIn(C.k250, n, 0.12), stS = 1.25 - 0.25 * ease(st);
  if (st > 0) scr.push(`<g opacity="${f1(Math.min(1, st * 1.4))}" transform="translate(${P.x + 885},${P.y + 112}) rotate(-6) scale(${f1(stS * 850) / 1000})"><rect x="-190" y="-58" width="380" height="116" fill="none" stroke="${X4.stamp}" stroke-width="7"/><rect x="-178" y="-46" width="356" height="92" fill="none" stroke="${X4.stamp}" stroke-width="2"/>` +
    `<text x="0" y="-8" font-family="Mono" font-size="26" letter-spacing="3" fill="${X4.stamp}" text-anchor="middle">LIMIT · LAW OF 1858</text><text x="0" y="34" font-family="Abril" font-size="42" fill="${X4.stamp}" text-anchor="middle">$250,000</text></g>`);
  // the bills, written in as they are read: [cue, label, amount, glint x]
  const rows = [[C.thermo, 'Thermometers', '$7,500.00'], [C.carpets, 'Carpets, shades and curtains', '$675,534.44'], [C.plast, 'One plasterer, two days’ work', '$138,187.00']];
  rows.forEach(([cue, lab, amt], i) => {
    const y = P.y + 236 + i * 138, u = xpIn(cue, n, 0.9), ua = xpIn(cue + (i === 0 ? 1.2 : i === 1 ? 2.6 : 1.5), n, 0.5);
    if (u <= 0) return;
    const w = lab.length * 23;
    scr.push(`<g><clipPath id="lgr${i}"><rect x="${P.x + 100}" y="${y - 50}" width="${f1(w * u + 10)}" height="70"/></clipPath><g clip-path="url(#lgr${i})">${xpInter(P.x + 100, y, lab, 38, X4.ink, 600)}</g></g>`);
    if (ua > 0) { scr.push(xpOp(ua, xpInter(P.x + P.w - 60, y, amt, 40, X4.ink, 800, 'end'))); s.push(x4Glint(P.x + P.w - 40, y - 32, 9, ua, n)); }
    s.push(`<rect x="${P.x + 100}" y="${y + 18}" width="${f1(660 * u)}" height="2" fill="#2B2418" opacity="0.18" stroke-dasharray="4 8"/>`);
  });
  scr.push(xpOp(xpIn(C.forT, n), penS(P.x + 480, P.y + 330, 'for thermometers', 30, -4)));
  scr.push(xpOp(xpIn(C.dec, n), penS(P.x + 480, P.y + 610, 'in December', 30, -4)));
  if (C.prince) scr.push(tag(P.x + 90, P.y + 700, 'THE TIMES: "THE PRINCE OF PLASTERERS"', xpIn(C.prince, n)));
  scr.push(xpOp(xpIn(C.two, n), `<path d="M${P.x + 360},${P.y + 512} q170,22 340,-4" fill="none" stroke="${XP.orange}" stroke-width="5" stroke-linecap="round"/>`));
  // the cost meter: a tall tube; the limit a line near the bottom; the fill climbs to 11 to 13 million
  const M = {x: 1420, y0: 900, y1: 300, w: 120}, top = 13e6, Yv = (v) => M.y0 - (M.y0 - M.y1) * v / top;
  const fillV = lerp(0, 250000, smooth(C.cost, C.k250 + 0.3, n)) + (11e6 - 250000) * smooth(C.y1871, C.million + 0.4, n) + 2e6 * smooth(C.million, C.fin, n) * (0.5 + 0.5 * Math.sin(n * 2.2));
  s.push(`<rect x="${M.x - 10}" y="${M.y1 - 40}" width="${M.w + 20}" height="${M.y0 - M.y1 + 60}" rx="16" fill="#0B1414" stroke="#111" stroke-width="5"/>`);
  for (let v = 0; v <= 13; v++) s.push(`<rect x="${M.x + M.w + 14}" y="${f1(Yv(v * 1e6))}" width="${v % 5 === 0 ? 26 : 14}" height="3" fill="${XP.pale}"/>`);
  s.push(`<rect x="${M.x}" y="${f1(Yv(fillV))}" width="${M.w}" height="${f1(M.y0 - Yv(fillV))}" fill="${XP.teal}" opacity="0.85"/><rect x="${M.x}" y="${f1(Yv(fillV))}" width="${M.w}" height="6" fill="${XP.cream}" opacity="0.8"/>`);
  const lim = xpIn(C.k250, n, 0.3);
  s.push(xpOp(lim, `<rect x="${M.x - 40}" y="${f1(Yv(250000) - 2)}" width="${M.w + 80}" height="5" fill="${XP.orange}"/>`));
  scr.push(xpOp(lim, xpMono(M.x - 50, Yv(250000) + 2, '$250,000', 24, XP.cream, 'end')));
  scr.push(xpOp(xpIn(C.cost, n), xpMono(M.x + M.w / 2, M.y1 - 70, 'COST', 26, XP.teal, 'middle', 4)));
  const big = xpIn(C.y1871, n, 0.4);
  if (big > 0) { const shown = fillV < 1e6 ? `$${Math.round(fillV / 1000)},000` : `$${(fillV / 1e6).toFixed(1)} million`;
    scr.push(xpOp(xpIn(C.between, n, 0.4), xpAbril(M.x + M.w / 2, M.y1 - 110, '$11 to 13 million', 46, XP.cream, 'middle')));
    scr.push(tag(M.x - 10, M.y0 + 50, 'BY 1871', big)); }
  scr.push(xpOp(xpIn(C.still, n), penS(P.x + 90, P.y + 800, 'and still not finished', 32, -4)));
  const body = `<g transform="translate(${f1(fx)},${f1(fy)}) scale(${f1(z * 1000) / 1000}) translate(${f1(-fx)},${f1(-fy)})">${s.join('')}${scr.slice(0, 2).join('')}</g>`;
  const defs = `<linearGradient id="lgdesk" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#000" stop-opacity="0.2"/><stop offset="1" stop-color="#000" stop-opacity="0.5"/></linearGradient>` +
    `<filter id="lgpaperf"><feTurbulence type="fractalNoise" baseFrequency="0.02 0.6" numOctaves="2" seed="3"/><feColorMatrix type="saturate" values="0"/></filter><pattern id="lgpaper" width="1920" height="1080" patternUnits="userSpaceOnUse"><rect width="1920" height="1080" filter="url(#lgpaperf)" opacity="0.25"/></pattern>`;
  // the page's own text moves with the page; the meter text is on the page layer too
  const pageText = `<g transform="translate(${f1(fx)},${f1(fy)}) scale(${f1(z * 1000) / 1000}) translate(${f1(-fx)},${f1(-fy)})">${scr.slice(2).join('')}</g>`;
  return frame(e3Defs(n, defs + X4_DEFS), '', body, pageText, n);
}

