function renderEscape(n, C = ES_CUE) {
  const P = (lon, lat) => E4_ATLP(lon, lat), ny = P(-74.0, 40.7), cuba = P(-75.8, 20.0), vigo = P(-8.72, 42.24);
  const seaA = [ny, P(-73, 37), P(-72.5, 30), P(-73.6, 24), cuba];
  const seaB = [cuba, P(-70, 22), P(-60, 27), P(-45, 33), P(-30, 38), P(-18, 41.5), vigo];
  const uA = smooth(C.escaped, C.cuba + 0.2, n), uB = smooth(C.spain - 0.2, C.where + 0.4, n);
  // the camera: on New York, south to Cuba, then pulled back across the Atlantic to Spain
  const cA = [ny[0] - 40, (ny[1] + cuba[1]) / 2], cB = [(cuba[0] + vigo[0]) / 2 + 120, (vigo[1] + cuba[1]) / 2 - 40];
  const v = smooth(C.spain - 0.6, C.where + 0.6, n), Z = lerp(1.35, 0.92, v) + 0.03 * smooth(C.where, C.end, n), ctr = [lerp(cA[0], cB[0], v), lerp(cA[1], cB[1], v)];
  const S = (p) => [960 + (p[0] - ctr[0]) * Z, 560 + (p[1] - ctr[1]) * Z], tr = `translate(${f1(960 - ctr[0] * Z)},${f1(560 - ctr[1] * Z)}) scale(${f1(Z * 1000) / 1000})`;
  const m = [`<rect width="1920" height="1080" fill="#132423"/>`];
  for (let lat = 10; lat <= 60; lat += 10) m.push(line([S(P(-100, lat)), S(P(10, lat))], '#2B4744', 1));
  for (let lon = -100; lon <= 10; lon += 10) m.push(line([S(P(lon, 8)), S(P(lon, 60))], '#2B4744', 1));
  m.push(`<path d="${E4_ATL}" transform="${tr}" fill="#24403D" stroke="#5F857F" stroke-width="${f1(2 / Z)}"/>`);
  const route = (pp, u) => { const q = xpPartial(pp.map(S), u); return q.length > 1 ? `<polyline points="${pts(q)}" fill="none" stroke="#111" stroke-width="10" stroke-dasharray="2 16" stroke-linecap="round"/><polyline points="${pts(q)}" fill="none" stroke="${XP.teal}" stroke-width="6" stroke-dasharray="2 16" stroke-linecap="round"/>` : ''; };
  m.push(route(seaA, uA), route(seaB, uB));
  const head = (pp, u) => { if (u <= 0 || u >= 1) return ''; const e = xpAt(pp.map(S), u); return `<circle cx="${f1(e[0])}" cy="${f1(e[1])}" r="10" fill="${XP.teal}" stroke="#111" stroke-width="3"/>`; };
  m.push(head(seaA, uA), head(seaB, uB));
  const dot = (p, k) => (k > 0 ? `<circle cx="${f1(S(p)[0])}" cy="${f1(S(p)[1])}" r="${f1(12 * k)}" fill="${XP.orange}" stroke="#111" stroke-width="3"/>` : '');
  m.push(dot(ny, xpIn(C.y1875 - 0.3, n)), dot(cuba, xpIn(C.cuba, n)), dot(vigo, xpIn(C.where, n)));
  const scr = [], nS = S(ny), cS = S(cuba), vS = S(vigo);
  scr.push(tag(nS[0] + 30, nS[1] - 20, 'NEW YORK · ESCAPED DECEMBER 1875', xpIn(C.y1875, n) * (1 - xpIn(C.spain, n))));
  scr.push(tag(cS[0] + 30, cS[1] + 50, 'CUBA · 1876', xpIn(C.cuba + 0.1, n)));
  scr.push(tag(vS[0] - 470, vS[1] + 60, 'VIGO, SPAIN · SEPTEMBER 1876', xpIn(C.where, n)));
  scr.push(xpOp(xpIn(C.where, n), penS(vS[0] - 420, vS[1] - 70, 'they had newspapers', 30, -4)));
  scr.push(xpOp(xpIn(C.y1875, n), tapeS(110, 92, 'THE ESCAPE', 54, -2, 1, 63)));
  return frame(e3Defs(n), '', m.join(''), scr.join(''), n);
}

/* ================= ep4_jobs (ch7): four offices, three paychecks (1870) ================= */
const JB_CUE = {held: 10.34, four: 10.76, once: 12.06, coll: 12.74, pay: 13.18, three: 13.96, same: 15.0, rich: 16.86};
const JB_JOBS = ['ASSEMBLYMAN', 'ALDERMAN', 'POLICE MAGISTRATE', 'COUNTY SUPERVISOR'];
function renderJobs(n, C = JB_CUE) {
  const s = [xpBoard(7)], scr = [];
  const z = 1 + 0.05 * smooth(C.held, C.rich + 1, n);
  scr.push(xpOp(xpIn(C.held - 0.3, n), tapeS(110, 92, 'PLUNKITT, 1870', 54, -2, 1, 64)));
  // Plunkitt as a picture-graph man in a top hat (faceless), in the middle
  s.push(x4At(960, 640, x4Pop(xpIn(C.held - 0.3, n, 0.45)), x4Man(0, 0, 220, '#1A2422', 'top', {stroke: XP.cream})));
  const pos = [[430, 330], [1490, 330], [430, 760], [1490, 760]];
  JB_JOBS.forEach((j, i) => {
    const k = x4Pop(xpIn(C.four + 0.28 * i, n, 0.35)), [x, y] = pos[i];
    if (k <= 0) return;
    s.push(xpOp(0.7, xpArrow([[x + (x < 960 ? 200 : -200), y], [960 + (x < 960 ? -70 : 70), 540]], xpIn(C.four + 0.28 * i + 0.2, n, 0.4), {w: 4, head: false})));
    scr.push(x4At(x, y, k, `<rect x="-230" y="-56" width="460" height="112" fill="${XP.paper}" stroke="#111" stroke-width="4"/><rect x="-230" y="-56" width="460" height="18" fill="${XP.mute2}"/>` +
      `<text x="0" y="22" font-family="Mono" font-size="${j.length > 14 ? 30 : 34}" letter-spacing="2" fill="#111" text-anchor="middle">${j}</text>`));
  });
  // three paychecks: an envelope with a gold glint flies from three of the four to him
  [0, 1, 3].forEach((i, k) => {
    const a = C.pay + 0.35 * k, u = smooth(a, a + 0.9, n), [x, y] = pos[i];
    if (u <= 0) return;
    const p = [lerp(x, 960 + (k - 1) * 84, ease(u)), lerp(y + (y < 540 ? 70 : -70), 720, ease(u)) - 90 * Math.sin(Math.PI * u)];
    s.push(xpEnvelope(p[0], p[1], 1.5) + x4Glint(p[0] + 26, p[1] - 20, 10, 1, n));
  });
  const ck = xpIn(C.three, n, 0.4);
  if (ck > 0) scr.push(xpOp(ck, penS(1090, 215, 'four jobs, three paychecks', 32, -3)));
  scr.push(xpOp(xpIn(C.same, n), tapeS(640, 920, 'AT THE SAME TIME', 54, -2, 1, 65)));
  return xpFrame(n, `<g transform="translate(960,560) scale(${f1(z * 1000) / 1000}) translate(-960,-560)">${s.join('')}</g>`, scr.join(''));
}

/* ================= ep4_graft (ch7): the swamp and the park ================= */
const GR_CUE = {say: 33.06, park: 34.86, quietly: 35.88, buy: 36.36, cheap: 37.98, then: 38.7, city: 39.16, buy2: 39.98, price: 41.44, anything: 41.96, asked: 44.1, today: 44.82, insider: 46.06, end: 47.5};
function renderGraft(n, C = GR_CUE) {
  const s = [], scr = [];
  const z = 1.0 + 0.06 * smooth(C.say, C.end, n), fx = 900, fy = 560;
  // a city map on paper: blocks, streets; out at the edge a swamp (reeds, standing water)
  s.push(`<rect width="1920" height="1080" fill="#16140F"/><rect x="120" y="110" width="1680" height="880" fill="#E6DCC4"/><rect x="120" y="110" width="1680" height="880" fill="url(#hatchT)" opacity="0.05"/>`);
  for (let x = 160; x < 1760; x += 150) for (let y = 150; y < 950; y += 120) { const sw = x > 1020 && x < 1500 && y > 300 && y < 760; if (sw) continue; s.push(`<rect x="${x}" y="${y}" width="120" height="90" fill="#B9AE94" stroke="#7A6F58" stroke-width="1.5"/>`); }
  const SW = {x: 1020, y: 300, w: 480, h: 460};
  const park = smooth(C.then, C.city + 0.8, n);
  s.push(`<rect x="${SW.x}" y="${SW.y}" width="${SW.w}" height="${SW.h}" fill="${park > 0.5 ? '#9DB59A' : '#A9B49A'}" stroke="#7A6F58" stroke-width="2"/>`);
  const r = rng(77);
  for (let k = 0; k < 9; k++) { const cx = SW.x + 40 + r() * (SW.w - 80), cy = SW.y + 40 + r() * (SW.h - 80); s.push(`<ellipse cx="${f1(cx)}" cy="${f1(cy)}" rx="${f1(30 + r() * 40)}" ry="${f1(12 + r() * 16)}" fill="#7F9C9A" opacity="${f1(0.7 * (1 - park))}"/>`); }
  for (let k = 0; k < 40; k++) { const cx = SW.x + 20 + r() * (SW.w - 40), cy = SW.y + 30 + r() * (SW.h - 40); s.push(`<path d="M${f1(cx)},${f1(cy)} l-4,-18 M${f1(cx)},${f1(cy)} l0,-22 M${f1(cx)},${f1(cy)} l5,-17" stroke="#4E6A4E" stroke-width="2" opacity="${f1(1 - 0.8 * park)}"/>`); }
  // the park plan lands: paths and trees drawn on
  if (park > 0) { s.push(xpOp(park, `<path d="M${SW.x},${SW.y + SW.h / 2} C${SW.x + 160},${SW.y + 120} ${SW.x + 320},${SW.y + 380} ${SW.x + SW.w},${SW.y + 200}" fill="none" stroke="#E6DCC4" stroke-width="10"/>` +
      `<ellipse cx="${SW.x + 300}" cy="${SW.y + 330}" rx="80" ry="40" fill="#7F9C9A"/>`));
    for (let k = 0; k < 18; k++) { const cx = SW.x + 40 + r() * (SW.w - 80), cy = SW.y + 40 + r() * (SW.h - 80), u = x4Pop(xpIn(C.then + 0.04 * k, n, 0.3)); s.push(x4At(cx, cy, u, `<circle r="20" fill="#3E6A4E" stroke="#111" stroke-width="2"/>`)); } }
  // the plan, outlined in teal when he hears of it
  const plan = xpIn(C.park, n, 0.6);
  if (plan > 0) s.push(xpOp(plan, xpArrow([[SW.x - 10, SW.y - 10], [SW.x + SW.w + 10, SW.y - 10], [SW.x + SW.w + 10, SW.y + SW.h + 10], [SW.x - 10, SW.y + SW.h + 10], [SW.x - 10, SW.y - 10]], plan, {w: 5, dash: '14 10', head: false})));
  // Plunkitt (top hat, faceless) at the left; the land is his
  const pk = x4Pop(xpIn(C.say, n, 0.4));
  s.push(x4At(520, 760, pk, x4Man(0, 0, 210, '#111', 'top', {stroke: '#7A6F58'})));
  const own = xpIn(C.buy, n, 0.5);
  if (own > 0) s.push(xpOp(own * (1 - 0.0), `<rect x="${SW.x + 16}" y="${SW.y + 16}" width="${SW.w - 32}" height="${SW.h - 32}" fill="none" stroke="#111" stroke-width="4" stroke-dasharray="4 10"/>`));
  // money: one small glint from him to the land (cheap); then many from City Hall to him (a good price)
  const g1 = smooth(C.buy, C.cheap + 0.4, n);
  if (g1 > 0 && g1 < 1) { const p = [lerp(560, SW.x + 60, g1), lerp(620, SW.y + 120, g1) - 80 * Math.sin(Math.PI * g1)]; s.push(x4Glint(p[0], p[1], 10, 1, n)); }
  const CH = [1650, 230];
  const chk = x4Pop(xpIn(C.city, n, 0.4));
  s.push(x4Icon('build', CH[0], CH[1], 1.15 * chk));
  for (let k = 0; k < 7; k++) { const a = C.buy2 + 0.22 * k, u = smooth(a, a + 1.0, n); if (u > 0 && u < 1) { const p = [lerp(CH[0], 560, u), lerp(CH[1] + 40, 600, u) - 120 * Math.sin(Math.PI * u)]; s.push(x4Glint(p[0], p[1], 11, 1, n)); } }
  const pile = smooth(C.price, C.price + 0.8, n);
  if (pile > 0) for (let k = 0; k < 6; k++) s.push(x4Glint(600 + (k % 3) * 24, 720 - Math.floor(k / 3) * 22, 9, pile, n + k));
  scr.push(tag(SW.x + 20, SW.y - 30, 'A SWAMP', xpIn(C.say - 0.3, n) * (1 - xpIn(C.then, n))));
  scr.push(tag(SW.x + 20, SW.y + SW.h + 62, 'THE CITY PLANS A PARK HERE', xpIn(C.park, n)));
  scr.push(tag(390, 900, 'PLUNKITT', xpIn(C.say - 0.3, n) * (1 - xpIn(C.buy, n))));
  scr.push(tag(330, 900, 'PLUNKITT BUYS IT FIRST · CHEAP', xpIn(C.buy, n)));
  scr.push(tag(SW.x + 20, SW.y - 30, 'THE CITY BUYS IT FROM HIM · A GOOD PRICE', xpIn(C.then + 0.45, n)));
  scr.push(xpOp(xpIn(C.anything, n), penS(240, 300, '“Anything dishonest in that?”', 36, -4)));
  scr.push(xpOp(xpIn(C.today - 0.35, n), tapeS(1000, 900, 'INSIDER DEALING', 60, -2, 1, 66)));
  scr.push(xpOp(xpIn(C.say, n), tapeS(110, 92, 'HONEST GRAFT', 54, -2, 1, 67)));
  return frame(e3Defs(n), '', `<g transform="translate(${fx},${fy}) scale(${f1(z * 1000) / 1000}) translate(${-fx},${-fy})">${s.join('')}</g>`, scr.join(''), n);
}

/* ================= ep4_tombstone (ch7): the epitaph he wanted ================= */
const TB_CUE = {liked: 47.6, wanted: 49.66, tomb: 50.46, seriously: 51.62, end: 52.7};
function renderTombstone(n, C = TB_CUE) {
  const s = [`<rect width="1920" height="1080" fill="#0E1817"/>`], scr = [];
  const z = 1.0 + 0.07 * smooth(C.liked, C.end + 0.6, n);
  // grass, a low fog, the stone
  s.push(`<rect x="0" y="830" width="1920" height="250" fill="#14231F"/><ellipse cx="960" cy="840" rx="1200" ry="60" fill="#A3BAB2" opacity="0.08"/>`);
  const up = smooth(C.liked - 0.2, C.liked + 0.6, n), sy = 860 + 40 * (1 - ease(up));
  s.push(`<g opacity="${f1(up)}"><path d="M640,${sy} L640,${sy - 520} Q640,${sy - 690} 960,${sy - 690} Q1280,${sy - 690} 1280,${sy - 520} L1280,${sy} Z" fill="#5F6F6B" stroke="#111" stroke-width="6"/>` +
    `<path d="M670,${sy - 10} L670,${sy - 515} Q670,${sy - 660} 960,${sy - 660} Q1250,${sy - 660} 1250,${sy - 515} L1250,${sy - 10}" fill="none" stroke="#7B8B86" stroke-width="3"/>` +
    `<rect x="600" y="${sy - 4}" width="720" height="40" fill="#4E5C58" stroke="#111" stroke-width="5"/><rect x="0" y="${sy + 30}" width="1920" height="30" fill="#14231F"/></g>`);
  const carve = (y, txt, size, k, font = 'Playfair') => (k > 0 ? `<text x="960" y="${f1(y)}" font-family="${font}" font-weight="900" font-size="${size}" fill="#1A2220" text-anchor="middle" opacity="${f1(k)}" style="paint-order:stroke" stroke="#8A9A95" stroke-width="1.2">${txt}</text>` : '');
  const k1 = xpIn(C.liked + 0.3, n, 0.5), k2 = xpIn(C.wanted, n, 0.5);
  scr.push(carve(sy - 520, 'George W. Plunkitt.', 58, k1 * up));
  scr.push(carve(sy - 400, 'He Seen His', 66, k2 * up), carve(sy - 315, 'Opportunities,', 66, k2 * up), carve(sy - 230, "and He Took 'Em.", 66, k2 * up));
  scr.push(tag(130, 1000, 'THE EPITAPH HE WANTED · PLUNKITT OF TAMMANY HALL, 1905', xpIn(C.liked, n)));
  scr.push(xpOp(xpIn(C.tomb - 0.3, n), penS(1330, 360, 'seriously', 38, -6)));
  return frame(e3Defs(n), '', `<g transform="translate(960,600) scale(${f1(z * 1000) / 1000}) translate(-960,-600)">${s.join('')}${scr.slice(0, 4).join('')}</g>`, scr.slice(4).join(''), n);
}

/* ================= ep4_scorecard (ch8): HELPER and THIEF ================= */
const SC_CUE = {helper: 0.48, coal: 2.3, fire: 5.98, jobs: 9.74, citizens: 12.86, mayors: 15.94, built: 17.66, markup: 22.64, now: 24.16, thief: 25.0, stole: 25.96, renters: 28.6, bought: 30.48, faked: 31.78, none: 32.78,
  paid: 35.66, decided: 37.28, end: 39.8};
const SC_ROWS = {
  helper: [['coal', 'COAL WHEN THE CITY STOPPED', 'coal'], ['fire', 'FIRST AT THE FIRE', 'fire'], ['job', 'JOBS NOBODY ELSE GAVE', 'jobs'], ['papers', 'CITIZENS, THEN ALDERMEN, MAYORS', 'citizens'], ['build', 'PARKS, SEWERS, BRIDGES', 'built']],
  thief: [['bag', 'STOLE MILLIONS', 'stole'], ['people', 'FROM TAXPAYERS AND RENTERS', 'renters'], ['ballot', 'BOUGHT VOTES, FAKED VOTES', 'bought'], ['tag', 'NO FAVOR WAS FREE', 'none'], ['boss', 'IT DECIDED WHO GOT WHAT', 'decided']],
};
function renderScorecard(n, C = SC_CUE) {
  const s = [xpBoard(8)], scr = [];
  // the camera leans toward the column being read (5 % at most, so nothing leaves the frame)
  const side = smooth(C.now - 0.4, C.thief, n), z = 1.04, cx = lerp(560, 1360, side), cy = 560;
  s.push(`<rect x="958" y="200" width="4" height="800" fill="${XP.mute2}"/>`);
  const col = (key, x0, hcue, title, seed) => {
    scr.push(xpOp(xpIn(hcue, n), tapeS(x0 + 40, 90, title, 66, -2, 1, seed)));
    SC_ROWS[key].forEach(([ic, lab, cue], i) => {
      const a = C[cue], k = x4Pop(xpIn(a, n, 0.4)), y = 300 + i * 150, lit = 1 - 0.35 * (key === 'helper' ? side : 1 - side);
      if (k <= 0) return;
      s.push(xpOp(lit, x4Icon(ic, x0 + 90, y, 1.12 * k)));
      scr.push(xpOp(xpIn(a - 0.1, n, 0.35) * lit, `<text x="${x0 + 175}" y="${y + 12}" font-family="Mono" font-size="${lab.length > 28 ? 27 : 31}" letter-spacing="1.5" fill="${XP.cream}">${lab}</text>`));
    });
  };
  col('helper', 140, C.helper, 'HELPER', 71);
  col('thief', 990, C.thief, 'THIEF', 72);
  if (n > C.markup) s.push(x4Glint(155, 920, 10, xpIn(C.markup, n, 0.4), n));
  scr.push(xpOp(xpIn(C.markup, n), penS(195, 1010, 'at a markup', 30, -3)));
  scr.push(xpOp(xpIn(C.paid, n), penS(1080, 1010, 'you paid with your vote', 30, -3)));
  return xpFrame(n, `<g transform="translate(${f1(cx)},${cy}) scale(${z}) translate(${f1(-cx)},${-cy})">${s.join('')}</g>`, scr.join(''));
}

/* ================= ep4_civil (ch8): the Pendleton Act, 1883 ================= */
const CV_CUE = {in1883: 41.58, law: 43.66, pend: 44.3, said: 45.38, jobs: 46.36, passed: 47.82, test: 48.3, not: 49.12, voted: 49.9, called: 51.22, civil: 51.86, but: 53.2};
function renderCivil(n, C = CV_CUE) {
  const s = [], scr = [];
  const z = 1.0 + 0.05 * smooth(C.in1883, C.but, n);
  s.push(x4Desk());
  // the exam paper on the desk
  const up = smooth(C.in1883 - 0.2, C.in1883 + 0.6, n), py = 150 + 50 * (1 - ease(up));
  s.push(`<g opacity="${f1(up)}" transform="rotate(-2, 700, 560)"><rect x="234" y="${py + 20}" width="920" height="820" fill="#000" opacity="0.5" filter="url(#soft)"/><rect x="220" y="${py}" width="920" height="820" fill="#EDE4D0"/>` +
    [0, 1, 2, 3, 4, 5, 6].map((k) => `<rect x="300" y="${py + 330 + k * 62}" width="${k % 3 === 2 ? 480 : 740}" height="3" fill="${X4.paperLine}"/>`).join('') + `</g>`);
  scr.push(`<g opacity="${f1(up)}" transform="rotate(-2, 700, 560)">${xpMono(680, py + 90, 'UNITED STATES CIVIL SERVICE COMMISSION', 24, '#5A5040', 'middle')}${xpAbril(680, py + 170, 'Examination', 72, X4.ink, 'middle')}` +
    `${xpMono(300, py + 260, 'NAME ............  SCORE ......', 24, '#5A5040')}</g>`);
  // two boxes: passed a test (ticked), voted the right way (crossed)
  const bx = 1220, b1 = 430, b2 = 650;
  const k1 = xpIn(C.passed, n, 0.4), k2 = xpIn(C.not, n, 0.4);
  if (k1 > 0) { s.push(xpOp(k1, `<rect x="${bx}" y="${b1 - 50}" width="70" height="70" fill="${XP.bg}" stroke="${XP.cream}" stroke-width="4"/>`)); scr.push(xpOp(k1, xpMono(bx + 112, b1, 'PASSED A TEST', 34, XP.cream))); }
  if (k2 > 0) { s.push(xpOp(k2, `<rect x="${bx}" y="${b2 - 50}" width="70" height="70" fill="${XP.bg}" stroke="${XP.cream}" stroke-width="4"/>`)); scr.push(xpOp(k2, xpMono(bx + 112, b2, 'VOTED THE RIGHT WAY', 34, XP.cream))); }
  const tk = xpIn(C.test, n, 0.4), xk = xpIn(C.voted + 0.4, n, 0.4);
  s.push(xpOp(tk, `<path d="M${bx + 12},${b1 - 18} l18,22 l36,-48" fill="none" stroke="#111" stroke-width="13" stroke-linecap="round"/><path d="M${bx + 12},${b1 - 18} l18,22 l36,-48" fill="none" stroke="${XP.teal}" stroke-width="7" stroke-linecap="round"/>`));
  s.push(xpOp(xk, `<path d="M${bx + 14},${b2 - 36} l42,42 M${bx + 56},${b2 - 36} l-42,42" stroke="#111" stroke-width="13" stroke-linecap="round"/><path d="M${bx + 14},${b2 - 36} l42,42 M${bx + 56},${b2 - 36} l-42,42" stroke="${XP.orange}" stroke-width="7" stroke-linecap="round"/>`));
  scr.push(xpOp(xpIn(C.in1883 - 0.1, n), tapeS(110, 92, 'THE PENDLETON ACT · 1883', 54, -2, 1, 73)));
  scr.push(xpOp(xpIn(C.jobs, n), penS(330, 600, 'for some federal jobs', 34, -3)));
  scr.push(card(1000, 760, 'Civil service', 'Government jobs filled by merit,|through tests, not as rewards.', null, xpIn(C.called, n, 0.4)));
  const defs = `<linearGradient id="lgdesk2" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#2A2620" stop-opacity="0.6"/><stop offset="1" stop-color="#000" stop-opacity="0.6"/></linearGradient>`;
  return frame(e3Defs(n, defs + X4_DEFS), '', `<g transform="translate(700,560) scale(${f1(z * 1000) / 1000}) translate(-700,-560)">${s.join('')}${scr.slice(0, 1).join('')}</g>`, scr.slice(1).join(''), n);
}

